pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny slivers of space (1-9) that are unlikely to be filled.
    // We heavily penalize small post_residuals, but reward values near 0 (perfect fit).
    let sliver_penalty = if post_res > 0.0 && post_res < 10.0 {
        (10.0 - post_res) * 5.0
    } else {
        0.0
    };

    // Incorporate lookahead: if next_item_size cannot fit in this post_residual,
    // penalize proportionally to the wasted space.
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size - post_residual) as f64 * 0.5
    } else {
        0.0
    };

    // Dynamic preference for tighter packing as the stream progresses.
    // Use a non-linear coupling: early on, we are more permissive; 
    // later, we prioritize minimizing post_residual (Best Fit).
    let progress_weight = 1.0 + (progress * 2.0);

    // Base score: prioritize smaller post_residual (Best Fit).
    // If bin_residual == bin_capacity, this is a new bin; assign a dynamic cost.
    let mut score = if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low,
        // or if we are forced to (fitting_bins_count == 0).
        (15.0 + (mean_residual * 0.5)) * progress_weight
    } else {
        post_res * progress_weight
    };

    // Apply penalties
    score += sliver_penalty + lookahead_penalty;

    // Reward bins that have a residual close to the current mean (load balancing)
    let deviation = (post_res - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "dead space" that is too small for common item sizes
    // We penalize residuals that are non-zero but smaller than the minimum likely size
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Harmonic packing: favor residuals that are multiples of common item sizes (e.g., 20, 25, 33)
    // to improve the probability of fitting future items perfectly.
    let harmonic_alignment = (post_residual % 20) as f64;
    score += harmonic_alignment * 0.5;

    // Lookahead logic: if the next item fits into the current post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // If this is the only fitting bin, heavily prioritize it to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // If we are evaluating a NEW bin (residual == capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are already very full
        // or if we are at the very start of the process.
        if open_bins_count > 0 && mean_residual > 25.0 {
            score += 30.0;
        } else {
            score += 60.0;
        }
    }

    // Progression scaling: as we approach the end of the stream, prioritize tight packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Class Penalty: Penalize residuals that are likely to strand small items.
    // We favor post_residuals that are either 0 (perfect fit) or large enough to fit common items.
    if post_residual > 0 {
        // Penalty for creating "sliver" residuals (1..9) which are hard to fill.
        if post_residual < 10 {
            score += 50.0 - (post_residual as f64 * 2.0);
        }
        // Harmonic reward: prioritize bins that align with the next item size.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    } else {
        // Perfect fit is always highly desirable.
        score -= 20.0;
    }

    // 2. Bin Consolidation Logic: 
    // If this is a new bin (bin_residual == bin_capacity), penalize opening it 
    // unless the number of currently fitting bins is very low.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing capacity.
            score += 150.0 - (open_bins_count as f64 * 2.0);
        } else {
            // If no bins fit, opening a new one is mandatory.
            score -= 10.0;
        }
    }

    // 3. Mean residual normalization:
    // Avoid creating bins that deviate significantly from the current mean residual.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 4. Progression weighting:
    // As we approach the end of the stream, prioritize closing bins (lower residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}
